import { RevisionCard } from '../revisionDeck';

// Fact cards for modules 13-18, ids mf-<module>-<3-digit sequence>.
// Authored from the app's assignment13-18 question bank (questions, correct
// answers and explanations), complementary to the existing revisionDeck
// entries for these modules. Each card holds ONE atomic fact; multi-fact
// statements were split into additional -101, -102, ... cards while every
// original id stays bound to its original fact/theme.

export const MODULE_FLASHCARDS_SLICE: Record<number, RevisionCard[]> = {
  13: [
    { id: 'mf-13-001', module: 13, front: 'Target population — defining characteristics', back: 'Defined by DEMOGRAPHIC and CLINICAL characteristics relevant to the research question (e.g. all circumcised children <5 years in Jaipur city).' },
    { id: 'mf-13-002', module: 13, front: 'Accessible population — defining characteristics', back: 'Defined by GEOGRAPHICAL and TEMPORAL characteristics — the reachable part of the target population available for sampling (e.g. circumcised children <5 at one government hospital).' },
    { id: 'mf-13-003', module: 13, front: 'Population hierarchy in participant selection', back: 'Target population → accessible population → sampling frame → study sample.' },
    { id: 'mf-13-101', module: 13, front: 'Study sample — position in the population hierarchy', back: 'The study sample is always a SUBSET of the accessible population.' },
    { id: 'mf-13-004', module: 13, front: 'Study sample vs accessible population', back: 'The study sample is a subset of the accessible population — never the reverse. Neither the target nor the accessible population is a subset of the study sample.' },
    { id: 'mf-13-005', module: 13, front: 'Sampling frame', back: 'The list of all members of the accessible population from which the study sample is actually drawn (e.g. hospital registers, household lists, electoral rolls).' },
    { id: 'mf-13-006', module: 13, front: 'Representativeness — definition', back: 'The extent to which the characteristics of the sample accurately reflect the characteristics of the population of interest.' },
    { id: 'mf-13-007', module: 13, front: 'Representativeness — pay-off', back: 'GENERALIZABILITY of the findings to the population of interest.' },
    { id: 'mf-13-102', module: 13, front: 'Representativeness and internal validity', back: 'Representativeness gives generalizability but does NOT create internal validity or reduce information/recall bias.' },
    { id: 'mf-13-008', module: 13, front: 'Internal validity — definition', back: 'The degree to which the observed findings lead to CORRECT INFERENCES about phenomena of interest within the study sample itself.' },
    { id: 'mf-13-009', module: 13, front: 'Internal validity vs generalizability', back: 'An internally valid result MAY or MAY NOT be generalizable to the target population.' },
    { id: 'mf-13-103', module: 13, front: 'A study without internal validity', back: 'It cannot be generalized to the target population at all.' },
    { id: 'mf-13-010', module: 13, front: 'Effect of biases on validity', back: 'Biases can affect BOTH internal and external validity — they are not confined to one type.' },
    { id: 'mf-13-011', module: 13, front: 'High non-response rate — effect on validity', back: 'It may affect the INTERNAL validity of a study and compromises generalizability.' },
    { id: 'mf-13-104', module: 13, front: 'High non-response rate — effect on study objective', back: 'It does NOT change the objective of the study.' },
    { id: 'mf-13-012', module: 13, front: 'Ways to minimize non-response', back: 'Repeat contact of participants · compensation for participants\u2019 time · less invasive and less sensitive questionnaires.' },
    { id: 'mf-13-013', module: 13, front: 'Less invasive, less sensitive questionnaires', back: 'They REDUCE NON-RESPONSE. (Their effect is on participation, not directly on statistical power or significance.)' },
    { id: 'mf-13-014', module: 13, front: 'Key factor choosing the accessible population & sampling approach', back: 'FEASIBILITY — cost, time and reachability drive the choice (more than simplicity, technology or reliability).' },
    { id: 'mf-13-015', module: 13, front: 'Factors while choosing the study sample & sampling approach', back: 'Feasibility · representativeness of the target population · sufficient numbers to test the proposed hypothesis.' },
    { id: 'mf-13-105', module: 13, front: 'Identification details as a sampling factor', back: 'Identification details of target-population individuals are NOT a required factor when choosing the study sample and sampling approach.' },
    { id: 'mf-13-016', module: 13, front: 'Guiding principles for selecting a suitable study population', back: 'Sample should be representative of the target population · cost and time of selection should be reasonable · numbers sufficient to account for random error.' },
    { id: 'mf-13-106', module: 13, front: 'Study-population selection — entire target population as a principle', back: '"Prefer selecting the ENTIRE target population" is NOT a guiding principle of study-population selection.' },
    { id: 'mf-13-017', module: 13, front: 'Selection of study participants depends on', back: 'Representativeness · acceptable cost · adequate size — all three together.' },
    { id: 'mf-13-018', module: 13, front: 'Reasons participants are excluded from a study', back: 'Interference with follow-up · ethical concerns · interference with data-collection quality · refusal/non-acceptance to participate.' },
    { id: 'mf-13-019', module: 13, front: 'Role of exclusion criteria', back: 'Exclusion criteria remove a SUBSET of the accessible population who, despite meeting inclusion criteria, are inappropriate to include.' },
    { id: 'mf-13-107', module: 13, front: 'Role of inclusion criteria', back: 'Specifying the population relevant to the research — who CAN enter the study.' },
    { id: 'mf-13-020', module: 13, front: 'Exclusion criterion in a rotavirus vaccine trial', back: 'Children who may leave the study area within a month — likely loss to follow-up makes them appropriate exclusions (age or vaccine status are inclusion criteria).' },
    { id: 'mf-13-021', module: 13, front: 'Zika birth-defects cohort — what CANNOT be an inclusion criterion', back: 'Pregnant women taking drugs known to cause birth defects — that is a reason to EXCLUDE (it interferes with the outcome).' },
    { id: 'mf-13-022', module: 13, front: 'PCOD drug trial — treatment status', back: 'Females with PCOD already UNDER TREATMENT are excluded from an efficacy trial (treatment modifies the outcome); reproductive-age women with PCOD are included.' },
    { id: 'mf-13-023', module: 13, front: 'Factors interfering with follow-up success', back: 'Out-migration from the study area · marriage of female participants causing relocation · refusals for follow-up.' },
    { id: 'mf-13-024', module: 13, front: 'Recruiting for clinical questions (diagnosis / treatment / prognosis)', back: 'Community recruitment is NOT easy or cost-effective for such severe-condition clinical questions — hospital/clinic-based patient recruitment is appropriate.' },
    { id: 'mf-13-025', module: 13, front: 'Random sampling in hospital-based selection', back: 'It IS possible (e.g. sampling patients from hospital records).' },
    { id: 'mf-13-026', module: 13, front: 'Obtaining a representative sample', back: 'Choose population and sampling methods wisely · guard against errors in applying inclusion criteria · monitor adherence to the criteria as the study progresses.' },
    { id: 'mf-13-027', module: 13, front: 'Non-response — study type with the higher rate', back: 'Generally HIGHER in observational studies than in experimental studies.' },
    { id: 'mf-13-108', module: 13, front: 'Non-response and generalizability', back: 'Non-response compromises the generalizability of the findings.' },
    { id: 'mf-13-109', module: 13, front: 'Non-response — how minimized', back: 'By methods that avoid participant discomfort (less invasive, less sensitive procedures).' },
    { id: 'mf-13-028', module: 13, front: 'Long-COVID example — target vs accessible population', back: 'Target: adult patients who recovered from COVID-19 in Bengaluru.\nAccessible: adults managed and recovered from COVID-19 at tertiary-care hospital XYZ in that city.' },
    { id: 'mf-13-029', module: 13, front: 'Sampling error', back: 'The chance difference between a sample statistic and the true population value arising because only part of the population is studied — reduced by increasing sample size.' },
    { id: 'mf-13-030', module: 13, front: 'Probability vs non-probability sampling', back: 'Probability: every member has a known chance — simple random, systematic, stratified, cluster.\nNon-probability: convenience, purposive/judgment, snowball.' },
    { id: 'mf-13-031', module: 13, front: 'Systematic sampling — when preferred', back: 'Preferentially used when the population is FINITE: every k-th unit is selected after a random start.' },
    { id: 'mf-13-032', module: 13, front: 'Simple random sampling', back: 'Every member of the accessible population has an equal, known probability of selection (lottery/random number tables) — the basic probability method.' },
    { id: 'mf-13-033', module: 13, front: 'Stratified sampling', back: 'The population is divided into homogeneous, non-overlapping STRATA (e.g. urban/rural, age groups) and a random sample is drawn from each.' },
    { id: 'mf-13-034', module: 13, front: 'Cluster sampling', back: 'Groups (clusters — villages, schools, wards) are randomly selected first, then individuals within them are studied; useful for large, geographically spread populations.' },
    { id: 'mf-13-035', module: 13, front: 'Convenience sampling', back: 'Non-probability method using easily reachable subjects (e.g. clinic attendees); quick and cheap but prone to selection bias and limits generalizability.' },
    { id: 'mf-13-036', module: 13, front: 'Purposive (judgmental) sampling', back: 'The investigator deliberately selects participants judged to be typical or informative; non-probability — no basis for statistical generalization.' },
    { id: 'mf-13-037', module: 13, front: 'Multistage sampling', back: 'Sampling carried out in stages: large units first (e.g. districts), then sub-units (villages), then individuals — practical for national/community surveys.' },
    { id: 'mf-13-038', module: 13, front: 'Large sample but unrepresentative', back: 'A large sample reduces random error but does NOT fix selection bias — an unrepresentative sample remains biased regardless of its size.' },
    { id: 'mf-13-039', module: 13, front: 'Order of applying eligibility criteria', back: 'INCLUSION criteria are applied first to define the eligible pool; EXCLUSION criteria are then applied WITHIN that pool.' },
    { id: 'mf-13-111', module: 13, front: 'Overlap between inclusion and exclusion lists', back: 'The two lists should NOT overlap — exclusion criteria operate only within the eligible pool defined by inclusion criteria.' },
    { id: 'mf-13-040', module: 13, front: 'Inclusion criteria — typical examples', back: 'Age or sex range, residence in a defined area, a defined diagnosis or exposure status, consent — who CAN enter the study.' },
    { id: 'mf-13-041', module: 13, front: 'Excluding participants likely to be lost — rationale', back: 'Planned migration or relocation makes follow-up unlikely — losing them later creates loss to follow-up and weakens both validity types.' },
    { id: 'mf-13-042', module: 13, front: 'Excluding participants for safety reasons', back: 'Those at HIGH RISK OF ADVERSE EFFECTS (e.g. pregnancy in a drug trial, pre-existing organ damage) are excluded on ETHICAL grounds.' },
    { id: 'mf-13-043', module: 13, front: 'Temporal boundary in defining a study population', back: 'Restricting recruitment to a defined TIME PERIOD (e.g. all cases in 2024) keeps the accessible population finite, feasible and clearly described.' },
    { id: 'mf-13-044', module: 13, front: 'Geographic boundary in defining a study population', back: 'A defined area (city, district, villages served by a facility) determines which part of the target population is actually reachable — it defines the ACCESSIBLE population.' },
    { id: 'mf-13-045', module: 13, front: 'Study population vs target population', back: 'Target population = the whole group to whom results should apply.\nStudy population = the participants actually selected (via accessible population and sampling) — usually a small, sampled subset.' },
    { id: 'mf-13-046', module: 13, front: 'Census vs sample', back: 'Studying the ENTIRE target population (census) is rarely feasible — cost, time and logistics make a well-selected SAMPLE the standard approach.' },
    { id: 'mf-13-047', module: 13, front: 'Sampling unit', back: 'The basic unit that is selected at each stage of sampling (individual, household, village). It may differ from the observation unit.' },
    { id: 'mf-13-048', module: 13, front: 'Consequence of an unrepresentative sample', back: 'Selection bias — the sample differs systematically from the target population, threatening external validity and sometimes internal validity.' },
    { id: 'mf-13-049', module: 13, front: 'Volunteer bias', back: 'Volunteers tend to differ systematically from non-volunteers (health awareness, motivation) — heavy reliance on volunteers can undermine representativeness.' },
    { id: 'mf-13-050', module: 13, front: 'Generalizing results requires', back: 'EXTERNAL VALIDITY — supported above all by the representativeness of the study sample relative to the target population.' }
  ],
  14: [
    { id: 'mf-14-001', module: 14, front: 'First step in developing a study', back: 'Formulating the RESEARCH QUESTION — before fixing the title, writing the background or planning the analysis.' },
    { id: 'mf-14-002', module: 14, front: 'Study life cycle — data-needs sequence', back: 'Identifying data needs → spelling out the research question → formulating study objectives → planning the analysis.' },
    { id: 'mf-14-003', module: 14, front: 'Study life cycle — activity sequence', back: 'Developing the research question → PLANNING the data analysis → data collection → data analysis.\nAnalysis is planned BEFORE data are collected.' },
    { id: 'mf-14-004', module: 14, front: 'Research cycle: step between objectives and instruments', back: 'The DATA ANALYSIS PLAN — it lies between formulating the study objectives and preparing the data collection instruments, ensuring analyzable information is collected.' },
    { id: 'mf-14-005', module: 14, front: 'Study objectives — stage at which they are defined', back: 'At the PLANNING stage of the study — they cannot be defined at any time, changed at the end, or added during implementation.' },
    { id: 'mf-14-006', module: 14, front: 'Good study objectives', back: 'Minimum in number, achievable and clear.' },
    { id: 'mf-14-101', module: 14, front: 'Types of study objectives by hierarchy', back: 'Study objectives can be PRIMARY and/or SECONDARY.' },
    { id: 'mf-14-102', module: 14, front: 'Effect of framing several study objectives', back: 'NO — framing SEVERAL objectives does NOT improve the planning and management of a study.' },
    { id: 'mf-14-007', module: 14, front: 'Ad hoc approach — consequences', back: 'SERIOUS DIFFICULTIES in analysis and interpretation — data are not aligned to pre-set objectives and indicators.' },
    { id: 'mf-14-008', module: 14, front: 'Ad hoc approach — advantages', back: 'Low development effort and the possibility of quick results — but the ACCURACY of the results is usually NOT high.' },
    { id: 'mf-14-009', module: 14, front: 'Ad hoc approach — suitability for study implementation', back: 'A structured, planned approach (objectives → indicators → tools → analysis plan) is required; ad hoc studies commonly fail at the interpretation stage.' },
    { id: 'mf-14-010', module: 14, front: 'Determining key indicators for a study', back: 'Requires ALL of: framing study objectives · identifying the parameters needed for the key indicators · choosing the right study design.' },
    { id: 'mf-14-011', module: 14, front: 'Principles for collecting information elements', back: 'Use variables that BEST REFLECT each information element · adopt standardized case definitions and laboratory criteria/normal ranges · choose the most accurate ways of collecting the information.' },
    { id: 'mf-14-012', module: 14, front: 'Common reasons research studies fail', back: 'Poorly defined/stated research question · vague or unrealistic timelines · inadequate supervision · lack of training of field investigators.' },
    { id: 'mf-14-013', module: 14, front: 'Inadequate supervision of field activities — effect', back: 'Generation of LOW-QUALITY data. (It does not save allocated funds nor force revision of study objectives.)' },
    { id: 'mf-14-014', module: 14, front: 'Deliverables of a health research project', back: 'Must be delivered within the defined TIMEFRAME · within the defined BUDGET · to the expected QUALITY standards.' },
    { id: 'mf-14-015', module: 14, front: 'Study efficiency levers', back: 'Time management · planning and scheduling of activities · budgeting — all three improve the efficiency of a research study.' },
    { id: 'mf-14-016', module: 14, front: 'Essentials of effective study planning & management', back: 'Time management · financial management · team work.' },
    { id: 'mf-14-103', module: 14, front: 'Reduction of sample size as a planning essential', back: 'NO — REDUCTION OF SAMPLE SIZE is NOT an essential of effective study planning and management.' },
    { id: 'mf-14-017', module: 14, front: 'Parts of project management', back: 'Time management · resource allocation · monitoring and supervision.' },
    { id: 'mf-14-104', module: 14, front: 'Protocol development as part of project management', back: 'NO — PROTOCOL DEVELOPMENT is not counted as part of project management.' },
    { id: 'mf-14-018', module: 14, front: 'Responsibilities in a health project — stage they are defined', back: 'During the PLANNING stage — not during initiation or conduct.' },
    { id: 'mf-14-019', module: 14, front: 'Gantt chart — uses', back: 'Develop the initial project schedule · report study progress · demonstrate milestones — all three.' },
    { id: 'mf-14-020', module: 14, front: 'Gantt chart vs other charts', back: 'Only the GANTT chart shows DURATION, timeline and sequence of activities. Bar charts, histograms and pie charts do not display a project timeline.' },
    { id: 'mf-14-021', module: 14, front: 'Budget size and project success', back: 'A high budget does NOT always result in successful project completion; planning, realistic timelines and supervision matter more.' },
    { id: 'mf-14-022', module: 14, front: 'Project timeline rule', back: 'The timeline should be NEITHER too long NOR too short — vague or unrealistic timelines are a classic reason for study failure.' },
    { id: 'mf-14-023', module: 14, front: 'SOPs in multi-centric studies', back: 'Having standard operating procedures IS a prerequisite for multi-centric studies (the claim that it is not, is not true).' },
    { id: 'mf-14-024', module: 14, front: 'Improving project implementation', back: 'Regular project review meetings · collecting ANALYZABLE information as a prerequisite · using validated methods for data collection.' },
    { id: 'mf-14-025', module: 14, front: 'Advantages of an analysis plan', back: 'Ensures analyzable information is collected · helps avoid comparisons not related to the objectives.' },
    { id: 'mf-14-105', module: 14, front: 'Analysis plan and data quality', back: 'NO — good-quality data depend on the data collection methods; the analysis plan itself does not ensure them.' },
    { id: 'mf-14-026', module: 14, front: 'Planning of a community-based thesis includes', back: 'Calculating the sample size · arranging transport to the community · writing the thesis — all are part of planning and program management.' },
    { id: 'mf-14-027', module: 14, front: 'Study design — deciding factors', back: 'The research question and OBJECTIVES — NOT the amount of funding available.' },
    { id: 'mf-14-028', module: 14, front: 'Sample size for a cross-sectional study — inputs', back: 'Assumed/reported PREVALENCE · CONFIDENCE interval (level) · acceptable PRECISION — all three.' },
    { id: 'mf-14-029', module: 14, front: 'Criterion for a good research question', back: 'A question based on ESTABLISHED THEORY and some research evidence — not on a hunch, complexity of wording, or an ill-defined hypothesis.' },
    { id: 'mf-14-030', module: 14, front: 'Non-measurable objective — example', back: '"Experiences shared by victims of domestic violence" — qualitative experience, not quantifiable as stated. Incidence or effect-size objectives are measurable.' },
    { id: 'mf-14-031', module: 14, front: 'Independent vs dependent variable (rank & coping study)', back: 'In the naval personnel coping-skills study: independent variable = RANK; dependent variable = COPING SKILLS.' },
    { id: 'mf-14-032', module: 14, front: 'Strengthening evidence for a new medication', back: 'ALL comparisons generate evidence: treated vs untreated outcomes · higher vs lower dose outcomes · adverse events with vs without the medication.' },
    { id: 'mf-14-033', module: 14, front: 'Appendectomy vs laparoscopy wound infections', back: 'The association may be due to a CONFOUNDING factor AND is better studied in a RANDOMIZED CONTROLLED TRIAL — both statements are true.' },
    { id: 'mf-14-034', module: 14, front: 'Pondicherry 1980\u20131995 cancer follow-up — design', back: 'PROSPECTIVE COHORT study — 7,000 adults enrolled in 1980 and followed forward until 1995 for cancer occurrence.' },
    { id: 'mf-14-035', module: 14, front: 'Improving validity of research', back: 'Take a truly REPRESENTATIVE sample of the population · eliminate extraneous factors and collect detailed information on CONFOUNDING factors — both.' },
    { id: 'mf-14-036', module: 14, front: 'Positive vs negative health indicators — definition', back: 'Positive = direct relationship with good health. Negative = inverse relationship with good health.' },
    { id: 'mf-14-106', module: 14, front: 'Positive health indicator — examples', back: 'Proportion of cured TB cases · life expectancy at birth.' },
    { id: 'mf-14-107', module: 14, front: 'Negative health indicator — examples', back: 'Incidence of AIDS · infant mortality rate (IMR).' },
    { id: 'mf-14-037', module: 14, front: 'Indicator', back: 'A measurable variable used to track health status or study processes; indicators are derived from the study objectives and can be positive or negative.' },
    { id: 'mf-14-038', module: 14, front: 'Analysis plan — stage it is framed', back: 'A PRIORI — during planning, before data collection. It follows the objectives so the right information elements are collected.' },
    { id: 'mf-14-039', module: 14, front: 'Pilot study in the project work plan', back: 'Included in planning to test feasibility of procedures (recruitment, tools, logistics) before the main study — not to test the hypothesis.' },
    { id: 'mf-14-040', module: 14, front: 'Work plan / schedule document', back: 'Lists study activities, the person responsible for each, and timelines; visually summarized as a Gantt chart.' },
    { id: 'mf-14-041', module: 14, front: 'Typical budget components of a study', back: 'Personnel · equipment · consumables/supplies · travel and field logistics · data collection and analysis costs · contingency.' },
    { id: 'mf-14-042', module: 14, front: 'Milestone', back: 'A significant planned checkpoint in the project timeline (e.g. ethical approval received, data collection completed) — demonstrated on the Gantt chart.' },
    { id: 'mf-14-043', module: 14, front: 'Monitoring — definition', back: 'Ongoing tracking of project activities and progress against the plan.' },
    { id: 'mf-14-108', module: 14, front: 'Supervision — definition', back: 'Guiding and checking the work of field staff; inadequate supervision produces low-quality data.' },
    { id: 'mf-14-044', module: 14, front: 'Typical project team', back: 'Principal Investigator, co-investigators, field investigators, data entry/statistical support — with responsibilities assigned during PLANNING.' },
    { id: 'mf-14-045', module: 14, front: 'Documentation of study conduct', back: 'Keep records of meetings, supervision visits, deviations from protocol and decisions taken — supports accountability and reporting.' },
    { id: 'mf-14-046', module: 14, front: 'Clearances built into the study timeline', back: 'Scientific, ethics (IEC) and any regulatory clearances are obtained BEFORE implementation and appear as early milestones in the work plan.' },
    { id: 'mf-14-047', module: 14, front: 'Pilot findings — planning inputs', back: 'Refinement of instruments, realistic TIMELINES, logistics and budget estimates before full implementation.' },
    { id: 'mf-14-048', module: 14, front: 'Reporting deliverables', back: 'Final report/thesis and scientific publication(s) — expected within the defined timeframe and quality standards.' },
    { id: 'mf-14-049', module: 14, front: 'Financial management in a study', back: 'Budgeting, tracking expenditure against the approved budget, and ensuring deliverables are achieved within the defined budget.' },
    { id: 'mf-14-050', module: 14, front: 'Vague timelines — mechanism of failure', back: 'Activities overrun, funds are exhausted before completion, and data quality suffers — hence timelines must be specific and realistic.' }
  ],
  15: [
    { id: 'mf-15-001', module: 15, front: 'Essential components of a data collection instrument', back: 'Identifier · confidentiality statement · instructions for the interviewer.' },
    { id: 'mf-15-101', module: 15, front: 'Incentives for the participant in a data collection instrument', back: 'NOT an essential component of a data collection instrument.' },
    { id: 'mf-15-002', module: 15, front: 'Identifier on a data collection form', back: 'A unique CODE NUMBER — never name or address — that LINKS different data collection forms for the same participant.' },
    { id: 'mf-15-003', module: 15, front: 'First step in designing a data collection instrument', back: 'DEFINE the information elements required — before deciding the method, drafting questions or piloting.' },
    { id: 'mf-15-004', module: 15, front: 'Steps in designing an instrument', back: 'Define information elements → draft the questions → pre-test the instrument.' },
    { id: 'mf-15-102', module: 15, front: 'Instrument design — analyzing the final data', back: 'NO — analyzing the final data is NOT a step in designing a data collection instrument.' },
    { id: 'mf-15-005', module: 15, front: 'Open-ended questions — best use', back: 'When the possible responses are UNKNOWN (exploratory work). Responses can later be coded and quantified.' },
    { id: 'mf-15-006', module: 15, front: 'Closed-ended questions — best use', back: 'Large samples needing QUICK, quantifiable analysis — answers are pre-specified and easy to code.' },
    { id: 'mf-15-007', module: 15, front: 'Types of closed-ended questions', back: 'Dichotomous (yes/no) · multiple-choice · Likert scale.\nUnstructured questions are NOT closed-ended.' },
    { id: 'mf-15-008', module: 15, front: 'Structured interview', back: 'The questions AND their order are PRE-DETERMINED — the interviewer does not improvise or reorder.' },
    { id: 'mf-15-009', module: 15, front: 'Face-to-face interview — profile', back: 'HIGHEST response rate and allows clarification — but carries the risk of INTERVIEWER bias.' },
    { id: 'mf-15-010', module: 15, front: 'Focus group discussion', back: 'A moderated group discussion (~6\u201310 participants) exploring shared perceptions and norms — a qualitative method.' },
    { id: 'mf-15-106', module: 15, front: 'FGD — suitability for sensitive individual data', back: 'FGDs are unsuitable for sensitive individual data (in-depth interviews are the method of choice).' },
    { id: 'mf-15-011', module: 15, front: 'Telephone interview — profile', back: 'Middle ground: faster than mail and allows clarification, but excludes people without phones and cannot use visual aids or cards.' },
    { id: 'mf-15-012', module: 15, front: 'Self-administered questionnaire', back: 'The respondent completes it alone — the method of choice for SENSITIVE topics (e.g. sexual behaviour) because privacy encourages truthful answers.' },
    { id: 'mf-15-013', module: 15, front: 'Using existing (secondary) data — advantage', back: 'Data collection is INEXPENSIVE and QUICK.' },
    { id: 'mf-15-103', module: 15, front: 'Using existing (secondary) data — limitation', back: 'The data were not tailored to your specific research question.' },
    { id: 'mf-15-014', module: 15, front: 'Secondary data analysis', back: 'Analyzing data collected by SOMEONE ELSE for ANOTHER PURPOSE (e.g. routine records, earlier surveys).' },
    { id: 'mf-15-015', module: 15, front: 'Pre-testing an instrument — how & by whom', back: 'Administered to a SMALL GROUP resembling the study population; ideally done by the SAME PEOPLE who will collect the final data.' },
    { id: 'mf-15-016', module: 15, front: 'Pre-testing identifies', back: 'Ambiguous questions · time required to complete the instrument · difficulties in following instructions — all fixed before the main study.' },
    { id: 'mf-15-017', module: 15, front: 'Pilot study purpose in data collection', back: 'To assess the FEASIBILITY of the data collection plan — not to test the hypothesis, estimate the final sample size, or publish results.' },
    { id: 'mf-15-018', module: 15, front: '"Validated" questionnaire', back: 'One that has been SHOWN TO MEASURE what it is intended to measure (usually against a reference/gold standard) — more than merely pre-tested or translated.' },
    { id: 'mf-15-019', module: 15, front: 'Face validity', back: 'Whether the instrument LOOKS like it measures what it is supposed to measure — judged by inspection, not by statistics.' },
    { id: 'mf-15-020', module: 15, front: 'Benefit of standardized instruments', back: 'Allows COMPARISON of results with other studies.' },
    { id: 'mf-15-105', module: 15, front: 'Standardization and systematic error', back: 'Standardizing instruments and procedures reduces SYSTEMATIC error (bias).' },
    { id: 'mf-15-021', module: 15, front: 'Reducing recall bias', back: 'Use MEMORY AIDS or records · keep the recall period SHORT. Long recall periods worsen recall bias.' },
    { id: 'mf-15-022', module: 15, front: 'Question order in a questionnaire', back: 'A LOGICAL FLOW — generally from GENERAL to SPECIFIC; not random, alphabetical, or ordered by difficulty.' },
    { id: 'mf-15-023', module: 15, front: 'A variable is', back: 'A characteristic that takes on DIFFERENT VALUES across participants (e.g. age, sex, blood pressure) — the opposite of a constant.' },
    { id: 'mf-15-024', module: 15, front: 'Objective data collection method', back: 'LABORATORY MEASUREMENTS — least dependent on participant report, unlike interviews, questionnaires and self-reports.' },
    { id: 'mf-15-025', module: 15, front: 'Quantifying open-ended responses', back: 'TRUE — open-ended responses can be coded and quantified after collection.' },
    { id: 'mf-15-026', module: 15, front: 'Electronic data capture (EDC) — benefits', back: 'Real-time data validation · reduction/elimination of separate data entry · fewer transcription errors — all three.' },
    { id: 'mf-15-027', module: 15, front: 'Electronic vs paper forms', back: 'The main advantage of electronic data collection is INSTANT data entry with built-in validation at the point of capture.' },
    { id: 'mf-15-028', module: 15, front: 'Improving survey response rates', back: 'Send reminders · keep the survey SHORT and easy to complete · explain the IMPORTANCE of the study — all help.' },
    { id: 'mf-15-029', module: 15, front: 'Maintaining confidentiality', back: 'Avoid collecting names/addresses when unnecessary · use CODES instead of names on forms · store data in a SECURE location.' },
    { id: 'mf-15-030', module: 15, front: 'Ethical considerations during data collection', back: 'Maintaining confidentiality · respecting the participant\u2019s right to withdraw · minimizing harm — all apply.' },
    { id: 'mf-15-031', module: 15, front: 'Timing of informed consent', back: 'Informed consent must be obtained BEFORE ANY data collection begins.' },
    { id: 'mf-15-032', module: 15, front: 'Questionnaire translation', back: 'Ensure CONCEPTUAL equivalence and simple language; translate forward AND BACK-translate to the original language to verify meaning.' },
    { id: 'mf-15-033', module: 15, front: 'Interviewer\u2019s manual contents', back: 'Study objectives · detailed instructions for EACH question · standard procedures for participant selection.' },
    { id: 'mf-15-034', module: 15, front: 'Role of the coder', back: 'Translates QUALITATIVE responses into NUMERICAL values (codes) so they can be entered and analyzed.' },
    { id: 'mf-15-035', module: 15, front: 'Changing question wording mid-study', back: 'NOT acceptable — it compromises STANDARDIZATION. Problems found during the study are documented, not reworded on the fly.' },
    { id: 'mf-15-036', module: 15, front: 'A well-designed instrument achieves', back: 'Reduced data-entry time · improved quality of data · minimized missing information — all three.' },
    { id: 'mf-15-037', module: 15, front: 'Sources of error in data collection', back: 'Interviewer bias · recall bias · non-response bias.' },
    { id: 'mf-15-104', module: 15, front: 'Standardized definitions and data-collection error', back: 'STANDARDIZED DEFINITIONS reduce error — they are not a source of it.' },
    { id: 'mf-15-038', module: 15, front: 'Ensuring data quality during the collection phase', back: 'Training the data collectors · supervising the process · conducting regular quality checks — all three.' },
    { id: 'mf-15-039', module: 15, front: 'Leading question', back: 'A question phrased so it SUGGESTS a desired answer (e.g. "You do exercise daily, don\u2019t you?") — must be avoided because it biases responses.' },
    { id: 'mf-15-040', module: 15, front: 'Instrument length', back: 'BRIEF and focused on the study objectives — not "as long as possible to collect all details".' },
    { id: 'mf-15-041', module: 15, front: 'Dichotomous question', back: 'A closed question with exactly TWO answer options (e.g. Yes/No, Ever/Never) — the simplest closed format.' },
    { id: 'mf-15-042', module: 15, front: 'Multiple-choice question', back: 'A closed question offering several MUTUALLY EXCLUSIVE options from which the respondent picks the allowed number.' },
    { id: 'mf-15-043', module: 15, front: 'Characteristics of a good interviewer', back: 'Knowledgeable about the study · NEUTRAL and non-judgmental · skilled in communication — all three.' },
    { id: 'mf-15-044', module: 15, front: 'Interviewer instructions', back: 'Printed on the instrument or in the manual so administration is UNIFORM across interviewers and sites.' },
    { id: 'mf-15-045', module: 15, front: 'Coding frame / codebook', back: 'A prepared scheme mapping verbatim (open-ended) answers to numbered categories BEFORE data entry — created by the coder.' },
    { id: 'mf-15-046', module: 15, front: 'Identifier should NOT be', back: 'Full name, address or date of birth — always a unique CODE NUMBER to protect identity.' },
    { id: 'mf-15-047', module: 15, front: 'Pre-testing — setting and personnel', back: 'In the FIELD, on people similar to the study population, performed by the actual data collectors — not by a panel of experts alone or on the target population at large.' },
    { id: 'mf-15-048', module: 15, front: 'Contingency (filter) question', back: 'A question that decides whether subsequent questions APPLY to the respondent — it works together with the skip pattern.' },
    { id: 'mf-15-049', module: 15, front: 'Questionnaire vs interview schedule', back: 'Questionnaire = SELF-administered (respondent reads and answers).\nInterview schedule = administered aloud by an interviewer. Item-design principles are shared.' },
    { id: 'mf-15-050', module: 15, front: 'Designing for analyzability', back: 'Every item must map to an information element/objective and a planned analysis — items that cannot be analyzed should not be asked.' }
  ],
  16: [
    { id: 'mf-16-001', module: 16, front: 'Hallmarks of good collected data', back: 'COMPLETE · READABLE · CONSISTENT (with accurate measurements).' },
    { id: 'mf-16-101', module: 16, front: 'Statistical significance as a data-collection check', back: 'Statistical significance is NOT a collection-level check of data quality.' },
    { id: 'mf-16-002', module: 16, front: 'Not a criterion for judging data quality', back: 'EXTERNAL VALIDITY (generalizability) and statistical significance are not data-quality checks. Quality is judged by accuracy, repeatability and precision.' },
    { id: 'mf-16-003', module: 16, front: 'Reliability denotes', back: 'PRECISION · REPEATABILITY · REPRODUCIBILITY — all three: the ability to produce SIMILAR results on repeated measurement.' },
    { id: 'mf-16-004', module: 16, front: 'Accuracy denotes', back: 'The ability to measure what it INTENDS to measure — correct ON AVERAGE, i.e. closeness to the true value.' },
    { id: 'mf-16-005', module: 16, front: 'Reliability vs accuracy — classic trap', back: 'The same result on repeated measurement = RELIABLE, not necessarily accurate. Accuracy requires agreement with the GOLD STANDARD.' },
    { id: 'mf-16-006', module: 16, front: 'Consistency is otherwise known as', back: 'REPRODUCIBILITY (a synonym within reliability).' },
    { id: 'mf-16-007', module: 16, front: 'Ideal measurement situation', back: 'BOTH accurate AND reliable — reliable-but-inaccurate or accurate-but-unreliable data are both deficient.' },
    { id: 'mf-16-008', module: 16, front: 'New test mean 90 (SD 5) vs gold standard mean 88 (SD 4.7)', back: 'Values close to the gold standard → the new diagnostic test is VALID (accuracy is judged against the gold standard).' },
    { id: 'mf-16-009', module: 16, front: 'Confirming validity of a measurement', back: 'Compare it against a GOLD STANDARD test/reference — a test yielding values close to the gold standard is valid.' },
    { id: 'mf-16-010', module: 16, front: 'Correct sequence of data collection steps', back: '1) PREPARATION (of the guide) → 2) TRAINING of collectors → 3) CHECKING for completeness → 4) VALIDATING.' },
    { id: 'mf-16-011', module: 16, front: 'Question-by-question (QbQ) guide', back: 'The ROADMAP for data collectors: instructions per question ensuring UNIFORMITY of collection and clarifying doubts. It is written for COLLECTORS, not participants.' },
    { id: 'mf-16-012', module: 16, front: 'QbQ guide — living document', back: 'TRUE — it can and should be revised as issues arise in the field.' },
    { id: 'mf-16-013', module: 16, front: 'Training of data collectors includes', back: 'On-site training · mock/simulated data collection sessions · discussing the study objectives · revising the guide per queries.' },
    { id: 'mf-16-102', module: 16, front: 'Training of data collectors — optional or essential', back: 'NO — training is ESSENTIAL, never optional.' },
    { id: 'mf-16-014', module: 16, front: 'Field-investigator training — questionnaire version used', back: 'An EARLY/DRAFT version of the questionnaire — collectors are trained on the FINAL, validated instrument.' },
    { id: 'mf-16-015', module: 16, front: 'On-site training', back: 'IS essential for data collectors (the claim that onsite training is not essential is false).' },
    { id: 'mf-16-016', module: 16, front: 'Foremost criterion for a field investigator', back: 'FAMILIARITY WITH THE LOCAL LANGUAGE — critical for accurate field data (above qualifications or clinical vocabulary).' },
    { id: 'mf-16-017', module: 16, front: 'Pilots — benefit for field investigators', back: 'Conducting a PILOT STUDY helps investigators understand the data collection process in real conditions.' },
    { id: 'mf-16-105', module: 16, front: 'Piloting and supervision', back: 'Piloting by field investigators is done UNDER SUPERVISION.' },
    { id: 'mf-16-018', module: 16, front: 'Ideal time to check completeness of data', back: 'BEFORE THE RESPONDENT LEAVES — gaps can be rectified immediately (not only at the end of collection or during cleaning).' },
    { id: 'mf-16-019', module: 16, front: 'Proper way to validate data', back: 'Repeat data collection in a RANDOMLY SELECTED SUBSET of the SAME population and compare with the original responses — not a new population, not a convenience subset, not the whole study.' },
    { id: 'mf-16-020', module: 16, front: 'Supportive supervision', back: 'ESSENTIAL for a good data collection process — supervisors guide, observe and troubleshoot field work.' },
    { id: 'mf-16-021', module: 16, front: 'Troubleshooting difficulties in data collection', back: 'Regular review meetings · facilitated discussion to identify issues · clarifying problems experienced by staff — all three.' },
    { id: 'mf-16-022', module: 16, front: 'Absolute don\u2019ts in data collection', back: 'MANIPULATION of data and MODIFYING the study objectives mid-collection.' },
    { id: 'mf-16-103', module: 16, front: 'Manipulation of data', back: 'An absolute don\u2019t in data collection.' },
    { id: 'mf-16-104', module: 16, front: 'Modifying study objectives mid-collection', back: 'An absolute don\u2019t in data collection.' },
    { id: 'mf-16-023', module: 16, front: 'Participant refuses one question mid-interview', back: 'CONTINUE the interview with the remaining questions — respect the refusal; do not end the interview, ask relatives, or pressure the participant.' },
    { id: 'mf-16-024', module: 16, front: 'Presenting the study to field investigators', back: 'REQUIRED — investigators must understand the study and its objectives to collect accurate data ("no need to present" is false).' },
    { id: 'mf-16-025', module: 16, front: 'Time pressure during data collection', back: 'DILUTES data quality — excessive pressure leads to errors and omissions.' },
    { id: 'mf-16-026', module: 16, front: 'Data collection tools should be', back: 'BOTH valid AND reliable — validity (measures what it intends) plus reliability (consistent on repetition).' },
    { id: 'mf-16-027', module: 16, front: 'Proper actions during collection', back: 'Referring to the data collection guide · checking quality of data · validating the data collection process — all are correct steps.' },
    { id: 'mf-16-028', module: 16, front: 'Field checks on filled forms', back: 'COMPLETENESS · CONSISTENCY · READABILITY — checked on site. Statistical significance is never a form-level check.' },
    { id: 'mf-16-029', module: 16, front: 'On-site quality check of filled instruments', back: 'The FIELD SUPERVISOR is mainly responsible for checking accuracy before the team leaves the location; investigators self-check as part of field checks.' },
    { id: 'mf-16-030', module: 16, front: 'Consistency check means', back: 'INTERNAL AGREEMENT of responses — e.g. age matching date of birth, related questions giving compatible answers.' },
    { id: 'mf-16-031', module: 16, front: 'Readability check means', back: 'Entries are LEGIBLE and comprehensible so they can be correctly understood, entered and interpreted later.' },
    { id: 'mf-16-032', module: 16, front: 'Completeness check means', back: 'All required fields are answered or EXPLICITLY marked as missing — no skipped or blank items.' },
    { id: 'mf-16-033', module: 16, front: 'Precision', back: 'The degree of agreement among REPEATED measurements (small spread) — a component of reliability.' },
    { id: 'mf-16-034', module: 16, front: 'Communication skills — importance for data collectors', back: 'Good communication builds rapport and elicits accurate, complete responses — a key selection/training criterion.' },
    { id: 'mf-16-035', module: 16, front: 'Choosing the right people as data collectors', back: 'Investigators should select suitable collectors (language, skills, availability) — training supports but cannot fully compensate a poor choice.' },
    { id: 'mf-16-036', module: 16, front: 'Validation is NOT', back: 'Re-collection in a NEW population · re-interviewing a CONVENIENCE subset · repeating the FULL collection — only a RANDOM subset of the SAME population.' },
    { id: 'mf-16-037', module: 16, front: 'Review of collected data — timing', back: 'Done DURING collection (ongoing review for quality and completeness), not only after data collection ends.' },
    { id: 'mf-16-038', module: 16, front: 'Study objectives during collection', back: 'Explained to collectors during training but NEVER MODIFIED while collection is ongoing.' },
    { id: 'mf-16-039', module: 16, front: 'Day-to-day ethics in data collection', back: 'Informed consent before collection · confidentiality of responses · the participant may decline any question without penalty.' },
    { id: 'mf-16-040', module: 16, front: 'Feedback loop from the field', back: 'Issues identified during collection are raised in review meetings, clarified with staff, and the guide is revised accordingly.' },
    { id: 'mf-16-041', module: 16, front: 'Supervision — how it protects data quality', back: 'It detects deviations, non-uniform administration and incomplete forms EARLY — before they accumulate into low-quality data.' },
    { id: 'mf-16-042', module: 16, front: 'Uniformity benefit of the guide', back: 'Different collectors and sites following the same QbQ guide produce COMPARABLE data (reduced inter-interviewer variation).' },
    { id: 'mf-16-043', module: 16, front: 'Documenting refusals and missing answers', back: 'Skipped questions are recorded EXPLICITLY (not left blank silently) so missingness can be quantified and handled later.' },
    { id: 'mf-16-044', module: 16, front: 'Mock data collection session', back: 'A rehearsal of the full procedure on peers/volunteers during training — builds skill and exposes practical problems before fieldwork.' },
    { id: 'mf-16-045', module: 16, front: 'Debriefing after field days', back: 'Collectors report difficulties and supervisors check the completed forms the same day — enabling immediate correction and guide revision.' },
    { id: 'mf-16-046', module: 16, front: 'QbQ guide contents', back: 'How to ASK each question · definitions of terms · permitted PROBES · how to RECORD responses · how to handle refusals.' },
    { id: 'mf-16-047', module: 16, front: 'Guide revision timing', back: 'AS AND WHEN issues are identified in the field — after review, and without breaking comparability of already-collected data.' },
    { id: 'mf-16-048', module: 16, front: 'Validation visit logistics', back: 'A FRACTION of participants are re-interviewed SHORTLY after the original visit, ideally by an independent collector, and responses compared.' },
    { id: 'mf-16-049', module: 16, front: 'Data collector conduct', back: 'Neutral and non-judgmental · follows the guide verbatim · offers no advice and never manipulates or fabricates answers.' },
    { id: 'mf-16-050', module: 16, front: 'End-to-end quality chain in data collection', back: 'Guide prepared → collectors trained (on final tool) → supervised collection with field checks → random-subset validation.' }
  ],
  17: [
    { id: 'mf-17-001', module: 17, front: 'Steps in data management', back: '1) Define variables, create the study database and dictionary · 2) Enter data, correct errors, create the dataset for analysis · 3) Back up and ARCHIVE the dataset.' },
    { id: 'mf-17-002', module: 17, front: 'Rules for a variable name', back: 'Clearly UNDERSTANDABLE and refers to the questionnaire · short, no spaces · CONSISTENT and without duplicates.' },
    { id: 'mf-17-003', module: 17, front: 'Coding rules at data entry', back: 'Prefer NUMERICAL coding · avoid cumbersome/complex codes · DECIDE IN ADVANCE the codes for "missing" and "not applicable" items.' },
    { id: 'mf-17-004', module: 17, front: 'Missing-value codes can mislead', back: 'Coding missing as 99 is ERRONEOUS when 99 lies inside the variable\u2019s legal range — e.g. systolic BP expected 60\u2013200, or fasting blood sugar 50\u2013150.' },
    { id: 'mf-17-005', module: 17, front: 'Handling missing continuous data (e.g. age missing in 13/100)', back: 'Code it with a designated missing value (e.g. "999") — do NOT delete the variable, invent values, or remove the participants.' },
    { id: 'mf-17-006', module: 17, front: 'Quality assurance in designing a data entry form', back: 'Legal values · minimum/maximum (range) checks · skip patterns · automatic coding.' },
    { id: 'mf-17-101', module: 17, front: 'Quality assurance — avoiding skip patterns', back: 'NO — AVOIDING skip patterns is NOT a quality-assurance measure in data entry design.' },
    { id: 'mf-17-007', module: 17, front: 'Specifications to check before data entry', back: 'Minimum and maximum values · legal codes · skip patterns · automatic coding, copying from the preceding record, and calculations.' },
    { id: 'mf-17-008', module: 17, front: 'Broad outline of a data entry design', back: 'Identifier → Demographics → Outcome → Exposure.' },
    { id: 'mf-17-009', module: 17, front: 'Data dictionary — when created', back: 'BEFORE data entry starts (created alongside database design — the claim that it is created after entry begins is FALSE).' },
    { id: 'mf-17-010', module: 17, front: 'Data dictionary contents', back: 'Questionnaire item · variable name · variable type · values/codes · brief description — it LINKS database variables to the questionnaire.' },
    { id: 'mf-17-102', module: 17, front: 'Data dictionary — number of records', back: 'NO — the number of records is NOT part of the data dictionary.' },
    { id: 'mf-17-011', module: 17, front: 'Data documentation includes', back: 'Structure (name, number of records) · Variables (names, values, coding) · History (creation, modification) · Storage information (media, location, backup).' },
    { id: 'mf-17-012', module: 17, front: 'Storage information documents', back: 'MEDIA, LOCATION and BACKUP information for the database.' },
    { id: 'mf-17-013', module: 17, front: 'Data catalogue', back: 'Describes ALL variables for future reference · useful when SHARING data · shows how each variable is coded.' },
    { id: 'mf-17-103', module: 17, front: 'Missing values in the data catalogue', back: 'Missing values should NOT be excluded from the data catalogue.' },
    { id: 'mf-17-014', module: 17, front: 'Normalized database', back: 'Has only ONE count per record — and it does NOT facilitate further data aggregation.' },
    { id: 'mf-17-106', module: 17, front: 'Normalized database and data aggregation', back: 'NO — a normalized database does NOT facilitate further data aggregation (that needs summarized/derived tables).' },
    { id: 'mf-17-015', module: 17, front: 'Mother\u2013daughter databases — design', back: 'Information collected at several LEVELS (e.g. village → household → individual → illness episode) is stored in SEPARATE linked databases.' },
    { id: 'mf-17-016', module: 17, front: 'Mother\u2013daughter databases — linking', back: 'Linked by a COMMON INDEX IDENTIFIER; each database CAN have its own unique identifier system.' },
    { id: 'mf-17-017', module: 17, front: 'Unique identifier (ID) properties', back: 'Unique to each participant · can be ALPHANUMERIC or a COMPOSITE number · maintains anonymity.' },
    { id: 'mf-17-104', module: 17, front: 'Sharing of an ID between two participants', back: 'NO — a unique identifier can NEVER be the same for two participants.' },
    { id: 'mf-17-018', module: 17, front: 'Identifier in the database', back: 'UNIQUE · maintained by a computerized index · secured by quality assurance procedures — all three.' },
    { id: 'mf-17-019', module: 17, front: 'Post-collection data management tasks', back: 'Create the study database · create the dataset for analysis · back up the dataset.' },
    { id: 'mf-17-105', module: 17, front: 'Data management — applying for ethics clearance', back: 'NO — applying for ETHICS CLEARANCE is NOT a data-management step.' },
    { id: 'mf-17-020', module: 17, front: 'EpiInfo — disadvantage', back: 'Built for WINDOWS OS only. (Strengths: questionnaire design, data entry with validation, analysis, mapping of location data.)' },
    { id: 'mf-17-021', module: 17, front: 'Key elements of data management', back: 'Data structure and data entry · individual and aggregated databases · mother\u2013daughter (hierarchical) databases.' },
    { id: 'mf-17-022', module: 17, front: 'Individual vs aggregated databases', back: 'Individual = one record per participant.\nAggregated = summarized counts/rates per group (e.g. per village) — used for program monitoring.' },
    { id: 'mf-17-023', module: 17, front: 'Instrument design for data management', back: 'The data collection instrument should be DATA-ENTRY FRIENDLY · outline the major data collection topics/items · support auto-coding.' },
    { id: 'mf-17-024', module: 17, front: 'Dichotomous smoking-history item — variable type', back: 'CATEGORICAL (a nominal, dichotomous variable).' },
    { id: 'mf-17-025', module: 17, front: '"Stage of cancer" recorded as Stage I\u2013IV — variable type', back: 'ORDINAL — ordered categories (also a categorical variable).' },
    { id: 'mf-17-026', module: 17, front: 'Nominal variable', back: 'Categories with NO natural order — sex, blood group, occupation, yes/no responses.' },
    { id: 'mf-17-027', module: 17, front: 'Continuous variable', back: 'Can take ANY value within a range — age, weight, blood pressure; recorded as numbers with units.' },
    { id: 'mf-17-028', module: 17, front: 'Discrete variable', back: 'Countable WHOLE numbers only — number of children, number of illness episodes.' },
    { id: 'mf-17-029', module: 17, front: 'Data-entry module — purpose of piloting', back: 'Tested BEFORE data collection so range checks, codes and skip logic work — an explicit data-quality measure.' },
    { id: 'mf-17-030', module: 17, front: 'Sample size software in data entry quality', back: 'IRRELEVANT — data-entry quality rests on legal values/range checks, piloting the module, and experienced data entry operators.' },
    { id: 'mf-17-031', module: 17, front: 'Experienced data entry operators', back: 'Contribute to data QUALITY (fewer entry errors) — part of quality assurance alongside validation rules.' },
    { id: 'mf-17-032', module: 17, front: 'Correcting entry errors', back: 'Detected errors (range violations, illegible values) are resolved by checking the SOURCE FORM — values are never guessed.' },
    { id: 'mf-17-033', module: 17, front: 'Back-up', back: 'Regular copies of the dataset stored SEPARATELY (different media/location) protect against data loss.' },
    { id: 'mf-17-034', module: 17, front: 'Archive', back: 'The final dataset PLUS documentation is retained after analysis, per protocol and funder requirements.' },
    { id: 'mf-17-035', module: 17, front: 'Dataset for analysis', back: 'The CLEANED, correctly coded, analysis-ready dataset created after entry and error correction.' },
    { id: 'mf-17-036', module: 17, front: 'Anonymity via ID', back: 'The master list linking names to IDs is kept SEPARATELY and securely from the analytical dataset.' },
    { id: 'mf-17-037', module: 17, front: 'Legal values', back: 'The set of ALLOWED codes/values for a variable — entry software rejects anything outside this set at the time of typing.' },
    { id: 'mf-17-038', module: 17, front: 'Skip patterns at entry', back: 'Entry forms ENFORCE skip logic so irrelevant fields stay empty and required follow-up fields are not missed.' },
    { id: 'mf-17-039', module: 17, front: 'Auto-coding / copy from preceding record', back: 'Speeds entry of repetitive fields (e.g. same village) — but must be used carefully to avoid propagating an error across records.' },
    { id: 'mf-17-040', module: 17, front: 'Hierarchical data levels — example', back: 'Village → household → individual → illness episode — each level can be stored in its own (daughter) database and linked when necessary.' },
    { id: 'mf-17-041', module: 17, front: 'The dictionary as a bridge', back: 'It LINKS the variables in the database to the questionnaire items — anyone can see which question produced which variable.' },
    { id: 'mf-17-042', module: 17, front: 'History in data documentation', back: 'WHEN the database was created and every subsequent MODIFICATION — an audit trail of changes.' },
    { id: 'mf-17-043', module: 17, front: 'Structure in data documentation', back: 'Database NAME, number of records, and file organization.' },
    { id: 'mf-17-044', module: 17, front: 'Documenting backup media/location', back: 'Recorded so that ANYONE can later locate and restore the data — part of storage documentation.' },
    { id: 'mf-17-045', module: 17, front: 'Data management plan — timing', back: 'Prepared during STUDY PLANNING: variables, database design and codes are defined BEFORE collection begins.' },
    { id: 'mf-17-046', module: 17, front: 'Confidentiality in data management', back: 'Coded IDs instead of names · restricted access · secure storage — names never sit in the analytical dataset.' },
    { id: 'mf-17-047', module: 17, front: 'Computerized index', back: 'Maintains the list of unique IDs so that DUPLICATE identifiers cannot be created.' },
    { id: 'mf-17-048', module: 17, front: 'QA procedures securing identifiers', back: 'Access control · validation of ID entry · periodic checks for duplicates — keeping the identifier system trustworthy.' },
    { id: 'mf-17-049', module: 17, front: 'Aggregated database — use', back: 'Program monitoring and reporting (counts, coverage, rates per area) — DERIVED from the individual-level (mother) database.' },
    { id: 'mf-17-050', module: 17, front: 'Overall order of data management', back: 'Define variables & dictionary → create database → pilot entry module → enter with validation → correct errors → clean → analysis dataset → back up & archive.' }
  ],
  18: [
    { id: 'mf-18-001', module: 18, front: 'Seven steps of data analysis strategy (order)', back: '1) Identify study type · 2) Identify main variables · 3) Become familiar with the data · 4) Characterize the study population · 5) Examine outcome/exposure association · 6) Create additional two-way tables · 7) Conduct advanced analysis.' },
    { id: 'mf-18-002', module: 18, front: 'First important step before data analysis', back: 'IDENTIFY THE STUDY DESIGN (study type) — it dictates the variables, tables and measures of association.' },
    { id: 'mf-18-003', module: 18, front: 'Stages of data analysis (order)', back: 'RECODING stage → DESCRIPTIVE stage → ANALYTICAL stage. Recoding of key variables comes FIRST.' },
    { id: 'mf-18-004', module: 18, front: 'Recoding stage', back: 'KEY variables are recoded (e.g. age grouped, categories combined) BEFORE descriptive and analytical analysis — not after them.' },
    { id: 'mf-18-005', module: 18, front: 'Descriptive stage', back: 'Characterizes the study population: frequency distributions, percentages, prevalence (cross-sectional) or incidence (cohort/surveillance).' },
    { id: 'mf-18-101', module: 18, front: 'Descriptive stage — regression models', back: 'NO — regression models do NOT belong to the descriptive stage.' },
    { id: 'mf-18-006', module: 18, front: 'Characterizing the study population — what is done', back: 'Frequency distribution of age · percentages of gender · baseline tables.' },
    { id: 'mf-18-102', module: 18, front: 'Population characterization — logistic regression', back: 'NO — LOGISTIC REGRESSION is NOT part of characterizing the study population.' },
    { id: 'mf-18-007', module: 18, front: 'Descriptive studies — what is wrong', back: 'They DESCRIBE the outcome in ONE group; they do NOT compare the outcome between 2 groups (that belongs to analytical studies).' },
    { id: 'mf-18-008', module: 18, front: 'Analytical stage — order within', back: 'UNIVARIATE analysis → STRATIFIED analysis → MULTIVARIATE analysis.' },
    { id: 'mf-18-009', module: 18, front: 'Analytical stage activities', back: 'Measures of association (OR/RR/PR) · outcome frequencies by age and gender · logistic regression.' },
    { id: 'mf-18-103', module: 18, front: 'Single-group outcome frequency — analysis stage', back: 'The DESCRIPTIVE stage — not the analytical stage.' },
    { id: 'mf-18-010', module: 18, front: 'Stratified analysis — example', back: 'Analysing the IUCD\u2013cervical cancer association SEPARATELY among women with multiple vs single sexual partners = STRATIFIED analysis.' },
    { id: 'mf-18-011', module: 18, front: 'Multivariable (multivariate) analysis', back: 'Performed LAST to ADJUST for potential confounders — never before univariate and stratified analyses.' },
    { id: 'mf-18-012', module: 18, front: 'Analyses to avoid', back: 'POST HOC analysis (not in the original plan) and DATA DRENCHING — both avoided.' },
    { id: 'mf-18-104', module: 18, front: 'Status of stratified analysis', back: 'STRATIFIED analysis is legitimate and encouraged — not among the analyses to avoid.' },
    { id: 'mf-18-013', module: 18, front: 'Data drenching', back: 'Tabulating/analysing EVERY possible variable and comparison without focus — it dilutes the a priori objectives and should be avoided.' },
    { id: 'mf-18-014', module: 18, front: 'Analysis plan depends on', back: 'Objectives of the study AND study type (descriptive vs analytical) — also the type of outcome variable.' },
    { id: 'mf-18-105', module: 18, front: 'Analysis plan — factors it does NOT depend on', back: 'NO — it does NOT depend on budget or availability of a statistician.' },
    { id: 'mf-18-015', module: 18, front: 'Analysis plan — timing', back: 'IN ADVANCE (a priori), during planning — so analyzable data get collected; NEVER after seeing the data.' },
    { id: 'mf-18-016', module: 18, front: 'Hypothesis testing is done in', back: 'ANALYTICAL epidemiological studies — descriptive studies only estimate and describe.' },
    { id: 'mf-18-017', module: 18, front: 'Analytical study purpose', back: 'TESTING OF HYPOTHESIS (vs estimation of parameters / description of populations in descriptive studies).' },
    { id: 'mf-18-018', module: 18, front: 'Data cleaning — what is done', back: 'Check and REMOVE duplicates · deal with MISSING observations · check RANGE and legal values.' },
    { id: 'mf-18-106', module: 18, front: 'Data cleaning — calculating strength of association', back: 'NO — calculating the strength of association is NOT part of data cleaning.' },
    { id: 'mf-18-019', module: 18, front: 'Analysis of large datasets — spreadsheets (Excel)', back: 'AVOIDED for data management and analysis of large datasets — use statistical software (e.g. Epi-Info).' },
    { id: 'mf-18-020', module: 18, front: 'Epi-Info', back: 'Free software used for data ENTRY and data ANALYSIS — and it can also create data collection instrument formats.' },
    { id: 'mf-18-021', module: 18, front: 'Acute and RARE outcome — design & measure', back: 'CASE-CONTROL study with the ODDS RATIO (rare outcomes suit the case-control design).' },
    { id: 'mf-18-022', module: 18, front: 'Acute and FREQUENT outcome — design & measure', back: 'COHORT study with the RELATIVE RISK (risk ratio).' },
    { id: 'mf-18-023', module: 18, front: 'OR calculation — mobile phone & acoustic neuroma', back: '24 cases (16 exposed), 72 controls (18 exposed).\n$\\text{OR} = \\dfrac{16 \\times 54}{8 \\times 18} = 6$.' },
    { id: 'mf-18-024', module: 18, front: 'OR calculation — instrumental delivery & autism', back: '100 cases (90 exposed), 200 controls (60 exposed).\n$\\text{OR} = \\dfrac{90 \\times 140}{10 \\times 60} = 21$.' },
    { id: 'mf-18-025', module: 18, front: 'RR calculation — OCP & breast cancer', back: '$\\text{RR} = \\dfrac{35/8{,}000}{33/22{,}000} \\approx 2.9$ — risk in OCP users vs non-users over 10 years.' },
    { id: 'mf-18-026', module: 18, front: 'Odds ratio — interpretation', back: 'Ratio of the ODDS of exposure among cases vs controls — the efficient measure when the outcome is RARE (case-control data).' },
    { id: 'mf-18-027', module: 18, front: 'Relative risk — interpretation', back: 'Ratio of INCIDENCE (risk) in exposed vs unexposed groups — the direct risk comparison available from COHORT data.' },
    { id: 'mf-18-028', module: 18, front: 'Prevalence ratio vs prevalence odds ratio', back: 'In ANALYTICAL cross-sectional studies the PREVALENCE RATIO is the preferred measure of association.' },
    { id: 'mf-18-029', module: 18, front: 'Risk ratio in a descriptive cross-sectional study', back: 'NOT meaningful — risk/prevalence ratios require COMPARISON groups, i.e. an analytical design.' },
    { id: 'mf-18-030', module: 18, front: 'Descriptive study measures', back: 'PREVALENCE for cross-sectional surveys · INCIDENCE for cohort or surveillance data.' },
    { id: 'mf-18-031', module: 18, front: 'Association examination is based on', back: 'The A PRIORI hypothesis — comparing exposure frequency between cases and controls (or outcome between exposed/unexposed) with the appropriate measure.' },
    { id: 'mf-18-032', module: 18, front: 'Become familiar with the data', back: 'An EARLY step: scan distributions, missingness and outliers before producing formal tables.' },
    { id: 'mf-18-033', module: 18, front: 'Identify main variables', back: 'After knowing the design: pick the outcome, exposure and confounders straight from the study objectives.' },
    { id: 'mf-18-034', module: 18, front: 'Two-way tables', back: 'Exposure × outcome cross-tabulations; ADDITIONAL two-way tables are created after the primary association has been examined (step 6 of 7).' },
    { id: 'mf-18-035', module: 18, front: 'Advanced analysis', back: 'MULTIVARIATE regression models — the LAST of the seven steps, after univariate and stratified analyses.' },
    { id: 'mf-18-036', module: 18, front: 'Correct overall analysis sequence', back: 'Recoding → frequency distribution → measures of association → multivariate analysis.' },
    { id: 'mf-18-037', module: 18, front: 'Order: multivariate vs univariate analysis', back: 'Multivariate analysis always FOLLOWS univariate and stratified analyses — never precedes them.' },
    { id: 'mf-18-038', module: 18, front: 'Timing of recoding relative to analysis stages', back: 'Recoding of key variables is done FIRST, before the descriptive stage — never after descriptive and analytical analysis.' },
    { id: 'mf-18-039', module: 18, front: 'Timing of analysis plan preparation', back: 'Prepared IN ADVANCE; post hoc analyses not in the original plan should be avoided.' },
    { id: 'mf-18-040', module: 18, front: 'Stage of logistic regression', back: 'Regression models belong to the analytical/advanced stage, never the descriptive stage.' },
    { id: 'mf-18-041', module: 18, front: 'Descriptive vs analytical — the dividing line', back: 'Describing outcome frequencies for ONE group = descriptive.\nCOMPARING groups (exposed vs unexposed, cases vs controls) = analytical.' },
    { id: 'mf-18-042', module: 18, front: 'Frequency distribution is used to', back: 'DESCRIBE / characterize the study population characteristics (first step of the descriptive stage).' },
    { id: 'mf-18-043', module: 18, front: 'Outcome frequency by age and gender', back: 'Part of the ANALYTICAL stage — subgroup comparisons, unlike a plain single-group frequency count.' },
    { id: 'mf-18-044', module: 18, front: 'Statistical software for analysis', back: 'Purpose-built packages — Epi-Info, SPSS, Stata, R — for entry, cleaning and analysis of large datasets; spreadsheets are not.' },
    { id: 'mf-18-045', module: 18, front: 'Comparing baseline characteristics of study groups', back: 'An ANALYTICAL activity (group comparison) — NOT part of characterizing a single study population.' },
    { id: 'mf-18-046', module: 18, front: 'Missing data in analysis', back: 'Handled during CLEANING (coded and documented) — before any stage of the actual analysis.' },
    { id: 'mf-18-047', module: 18, front: 'Timing of additional two-way tables', back: 'Created AFTER examining the main outcome/exposure association — step 6 of the seven-step strategy.' },
    { id: 'mf-18-048', module: 18, front: 'Study type identification drives', back: 'The choice of measures (prevalence vs incidence; OR vs RR vs PR) and the structure of the tables.' },
    { id: 'mf-18-049', module: 18, front: 'A priori', back: 'Planned BEFORE the data are seen/analysed, per the original objectives — the opposite of post hoc.' },
    { id: 'mf-18-050', module: 18, front: 'Descriptive vs analytical study output', back: 'Descriptive → estimates (prevalence, incidence, means) in ONE group.\nAnalytical → measures of association and hypothesis tests BETWEEN groups.' }
  ]
};